// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Strings.sol"; // Add this import
import "./SDGEventFactory.sol";
import "./SDGImpactNFT.sol";

contract SDGDonation is Ownable, ReentrancyGuard {
    using Strings for uint256; // Add this line
    SDGEventFactory public eventFactory;
    SDGImpactNFT public nftContract;

    mapping(address => mapping(uint8 => uint256)) public donorContributions;
    mapping(address => uint256) public totalDonations;

    event DonationSuccessful(
        address donor,
        uint256 eventId,
        uint8 sdg,
        uint256 amount,
        bool nftMinted
    );

    constructor(address _eventFactory, address _nftContract) 
        Ownable(msg.sender) 
    {
        eventFactory = SDGEventFactory(_eventFactory);
        nftContract = SDGImpactNFT(_nftContract);
    }

    function donate(uint256 eventId) external payable nonReentrant {
        SDGEventFactory.Event memory event_ = eventFactory.getEvent(eventId);
        
        // Simple input validation for beginners
        require(msg.value > 0, "Donation required");
        require(event_.isActive, "Event inactive");
        require(block.timestamp < event_.deadline, "Event ended");
        require(msg.value >= event_.minDonation, "Below minimum");
        require(msg.value <= event_.maxDonation, "Above maximum");

        // Track donations
        donorContributions[msg.sender][event_.sdgCategory] += msg.value;
        totalDonations[msg.sender] += msg.value;

        // Mint NFT if threshold met
        bool minted = false;
        if(msg.value >= event_.nftMintThreshold) {
            string memory uri = string(abi.encodePacked(
            "https://api.sdgfunder.com/nft/",
            Strings.toString(uint256(event_.sdgCategory)), // Convert to uint256 first
             "/",
            block.timestamp.toString()
        ));
        nftContract.safeMint(msg.sender, event_.sdgCategory, uri); // Now using 'uri'
        minted = true;
    }

        emit DonationSuccessful(
            msg.sender,
            eventId,
            event_.sdgCategory,
            msg.value,
            minted
        );
    }

    // Simple withdrawal for contract owner
    function withdrawFunds(address payable to) external onlyOwner nonReentrant {
        require(to != address(0), "Invalid address");
        to.transfer(address(this).balance);
    }
}

contracts/SDGImpactNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

contract SDGImpactNFT is ERC721, Ownable {
    using Strings for uint256;
    
    mapping(uint256 => uint8) public tokenSDG;
    mapping(uint256 => string) private _tokenURIs;
    uint256 private _nextTokenId;

    constructor() ERC721("SDGImpactNFT", "SDGNFT") Ownable(msg.sender) {}

    event NFTMinted(address indexed to, uint256 tokenId, uint8 sdg);

    // Helper function to check token existence
    function _tokenExists(uint256 tokenId) internal view returns (bool) {
        return _ownerOf(tokenId) != address(0);
    }

    function safeMint(address to, uint8 sdg, string memory uri) 
        external 
        onlyOwner 
        returns (uint256) 
    {
        require(sdg >= 1 && sdg <= 17, "Invalid SDG ID");
        
        uint256 tokenId = _nextTokenId++;
        _safeMint(to, tokenId);
        _setTokenURI(tokenId, uri);
        tokenSDG[tokenId] = sdg;
        
        emit NFTMinted(to, tokenId, sdg);
        return tokenId;
    }

    function _setTokenURI(uint256 tokenId, string memory uri) internal {
        require(_tokenExists(tokenId), "Token doesn't exist"); // Using our helper
        require(bytes(_tokenURIs[tokenId]).length == 0, "URI already set");
        _tokenURIs[tokenId] = uri;
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        require(_tokenExists(tokenId), "Token doesn't exist"); // Using our helper
        return _tokenURIs[tokenId];
    }
}

contracts/SDGEventFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

contract SDGEventFactory is Ownable {
    struct Event {
        address organizer;
        uint256 goal;
        uint256 deadline;
        string ipfsSDGMetadata;
        uint8 sdgCategory; // 1-17 for UN SDGs
        bool isActive;
        uint256 minDonation;
        uint256 maxDonation;
        uint256 nftMintThreshold;
    }

    Event[] public events;

    constructor() Ownable(msg.sender) {} // Simple owner initialization

    event EventCreated(uint256 eventId, address organizer, uint8 sdgCategory);

    function createEvent(
        uint256 _goal,
        uint256 _deadline,
        string memory _ipfsSDGMetadata,
        uint8 _sdgCategory,
        uint256 _minDonation,
        uint256 _maxDonation,
        uint256 _nftMintThreshold
    ) external {
        require(_sdgCategory >= 1 && _sdgCategory <= 17, "Invalid SDG");
        require(_deadline > block.timestamp + 5 minutes, "Deadline too soon");
        require(_minDonation <= _maxDonation, "Invalid donation range");

        uint256 eventId = events.length;
        events.push(Event({
            organizer: msg.sender,
            goal: _goal,
            deadline: _deadline,
            ipfsSDGMetadata: _ipfsSDGMetadata,
            sdgCategory: _sdgCategory,
            isActive: true,
            minDonation: _minDonation,
            maxDonation: _maxDonation,
            nftMintThreshold: _nftMintThreshold
        }));

        emit EventCreated(eventId, msg.sender, _sdgCategory);
    }

    function toggleEventActive(uint256 eventId, bool isActive) external {
        require(msg.sender == events[eventId].organizer || msg.sender == owner(), "Not authorized");
        events[eventId].isActive = isActive;
    }

    function getEvent(uint256 eventId) external view returns (Event memory) {
    return events[eventId];
}
}

